const $=s=>document.querySelector(s), scene=new T.Scene();scene.background=new T.Color('#92c8e9');scene.fog=new T.Fog('#c0dce8',800,12000);const sky=addSky(scene);
const renderer=new T.WebGLRenderer({antialias:false});renderer.setPixelRatio(1);renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.05;$('#world').append(renderer.domElement);renderer.domElement.tabIndex=0;
const camera=new T.PerspectiveCamera(68,innerWidth/innerHeight,.15,18000);camera.rotation.order='YXZ';const resize=()=>{renderer.setSize(Math.floor(innerWidth*.65),Math.floor(innerHeight*.65),false);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix()};addEventListener('resize',resize);resize();const ambient=new T.HemisphereLight('#e2f1ff','#a5b5aa',1.85);scene.add(ambient);const sun=new T.DirectionalLight('#fff9ee',2.1);sun.position.set(-180,230,100);scene.add(sun);
