const destinations=new Map();for(const [value,name]of [['fitzherbert','Fitzherbert Road'],['main','Main Road']]){const choices=roads.filter(r=>r.bridge&&r.name===name).sort((a,b)=>a.p[0].length()-b.p[0].length());if(choices.length)destinations.set(value,value==='main'?(choices.find(r=>r.id.startsWith('175975423-'))||choices[0]):choices[0])}
