$('#play').onclick=play;$('#resume').onclick=play;$('#reset').onclick=()=>{reset();play()};$('#help').onclick=()=>{if(!started){$('#pause').classList.remove('hidden')}else pause()};addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea'))return;keys[e.key.toLowerCase()]=true;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(e.key.toLowerCase()==='r')reset();if(e.key.toLowerCase()==='m'&&!e.repeat){if(!aerial){lastGround={x:camera.position.x,z:camera.position.z};camera.position.y+=35;pitch=-.45;aerial=true}else{aerial=false;const landing=findLanding(world,camera.position.x,camera.position.z,lastGround);camera.position.x=landing.x;camera.position.z=landing.z;camera.position.y=world.walkHeight(camera.position.x,camera.position.z)+2;pitch=0}$('#flight-mode').textContent=aerial?'DRONE · SPACE ↑ / C ↓':'ON FOOT';}if(e.key.toLowerCase()==='n'&&!e.repeat)cycle.skip();if(e.key==='Escape')pause()});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);addEventListener('blur',()=>{if(started)pause()});document.addEventListener('pointerlockchange',()=>{if(!document.pointerLockElement&&active&&!touch)pause()});addEventListener('mousemove',e=>{if(document.pointerLockElement&&active&&performance.now()>lookReadyAt){yaw-=e.movementX*.0025;pitch=Math.max(-1.2,Math.min(1.2,pitch-e.movementY*.0025))}});
let lastTouch;renderer.domElement.addEventListener('pointerdown',e=>{if(!document.pointerLockElement){lastTouch=[e.clientX,e.clientY];if(e.pointerType==='touch')touch=true}if(started&&!active)play()});renderer.domElement.addEventListener('pointermove',e=>{if(lastTouch&&active&&!document.pointerLockElement){yaw-=(e.clientX-lastTouch[0])*.006;pitch=Math.max(-1.1,Math.min(1.1,pitch-(e.clientY-lastTouch[1])*.006));lastTouch=[e.clientX,e.clientY]}});addEventListener('pointerup',()=>{lastTouch=null;for(const k in keys)if(touch)keys[k]=false});document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();touch=true;keys[b.dataset.key]=true;b.setPointerCapture(e.pointerId)};b.onpointerup=()=>keys[b.dataset.key]=false});renderer.domElement.style.touchAction='none';
for(const r of roads)r.mapBounds=[Math.min(...r.p.map(p=>p.x)),Math.min(...r.p.map(p=>p.y)),Math.max(...r.p.map(p=>p.x)),Math.max(...r.p.map(p=>p.y))];
const ctx=$('#map').getContext('2d');function minimap(){ctx.fillStyle='#33483a';ctx.fillRect(0,0,210,170);const scale=aerial?.055:.18,X=x=>105+(x-camera.position.x)*scale,Y=z=>85+(z-camera.position.z)*scale;world.coast.drawMinimap(ctx,X,Y,camera.position,scale);ctx.strokeStyle='#427e9b';ctx.lineWidth=2;for(const r of world.hydro.rivers){ctx.beginPath();r.p.forEach((p,i)=>i?ctx.lineTo(X(p.x),Y(p.z)):ctx.moveTo(X(p.x),Y(p.z)));ctx.stroke()}ctx.strokeStyle='#8b9b82';ctx.lineWidth=2;for(const r of roads){const b=r.mapBounds,margin=120/scale;if(b[2]<camera.position.x-margin||b[0]>camera.position.x+margin||b[3]<camera.position.z-margin||b[1]>camera.position.z+margin)continue;ctx.beginPath();r.p.forEach((p,i)=>i?ctx.lineTo(X(p.x),Y(p.y)):ctx.moveTo(X(p.x),Y(p.y)));ctx.stroke()}for(const q of markers){ctx.fillStyle=q.found?'#9ead87':'#e6efa1';ctx.fillRect(X(q.p.x)-2,Y(q.p.y)-2,4,4)}ctx.save();ctx.translate(105,85);ctx.rotate(-yaw);ctx.fillStyle='#e9f8ab';ctx.beginPath();ctx.moveTo(0,-7);ctx.lineTo(-4,5);ctx.lineTo(4,5);ctx.closePath();ctx.fill();ctx.restore()}
let last=performance.now(),clock=0,frame=0;function animate(now){requestAnimationFrame(animate);const dt=Math.min((now-last)/1000,.05);last=now;clock+=dt;const lighting=cycle.update(dt,(active||!started)&&!document.hidden);const moving=(active||!started)&&!document.hidden;world.hydro.update(moving?dt:0);world.forest.update(camera.position);world.roofDetail.update(camera.position);world.region.update(camera.position);world.coast.update(moving?dt:0,lighting);traffic.update(moving?dt:0,camera.position,lighting.night);if(active){const movement=movePlayer({position:camera.position,yaw,pitch,keys,dt,drone:aerial,world,clock});$('#boundary').classList.toggle('hidden',!movement.atBoundary);camera.rotation.set(pitch,yaw,0);for(const q of markers){if(!q.found&&q.p.distanceTo(new T.Vector2(camera.position.x,camera.position.z))<12){q.found=true;q.m.material.color.set('#819c70');const n=markers.filter(q=>q.found).length;$('#count').textContent=`Discover ${n} / 4 places`;$('#toast').textContent=n===4?'Valley explored. Take the long way home.':`Place discovered · ${q.name}`;$('#toast').style.opacity=1;setTimeout(()=>$('#toast').style.opacity=0,3500)}}}else if(!started){camera.rotation.set(-.05,initialYaw+Math.sin(clock*.06)*.12,0)}for(const q of markers){q.m.rotation.y=clock;q.m.position.y=ground(q.p.x,q.p.y)+3+Math.sin(clock*2)*.4}if(frame++%12===0){minimap();$('#place').textContent=world.tunnels?.at(camera.position.x,camera.position.z,camera.position.y)?'Wainuiomata Tunnel':nearest(camera.position.x,camera.position.z).name}renderer.render(scene,camera)}animate(performance.now());
